(function () {
  // 서버 집계 데이터 → SVG 선 그래프
  var data = /*[[${chart}]]*/ [];
  var svg = document.getElementById('visitChart');
  if (!svg || !data.length) return;
  var W = Math.max(480, svg.clientWidth || 700), H = 240, padL = 20, padR = 24, padT = 44, padB = 46;
  svg.setAttribute('viewBox', '0 0 ' + W + ' ' + H);
  var n = data.length, max = 0;
  data.forEach(function (d) { if (d.v > max) max = d.v; });
  if (max === 0) max = 1;
  var x = function (i) { return padL + (W - padL - padR) * (n === 1 ? 0.5 : i / (n - 1)); };
  var y = function (v) { return padT + (H - padT - padB) * (1 - v / max); };
  var NS = 'http://www.w3.org/2000/svg';
  function el(t, a) { var e = document.createElementNS(NS, t); for (var k in a) e.setAttribute(k, a[k]); return e; }
  // 가로 보조선
  [0, .5, 1].forEach(function (r) {
    var yy = padT + (H - padT - padB) * r;
    svg.appendChild(el('line', { 'class': 'grid', x1: padL, x2: W - padR, y1: yy, y2: yy }));
  });
  // 선
  var pts = data.map(function (d, i) { return x(i) + ',' + y(d.v); }).join(' ');
  svg.appendChild(el('polyline', { 'class': 'line', points: pts }));
  // 점 · 라벨
  data.forEach(function (d, i) {
    var cx = x(i), cy = y(d.v), last = i === n - 1;
    svg.appendChild(el('circle', { 'class': 'dot' + (last ? ' today' : ''), cx: cx, cy: cy, r: 3 }));
    if (true) {
      if (last) svg.appendChild(el('rect', { 'class': 'today-bg', x: cx - 14, y: H - padB + 11, width: 28, height: 18, rx: 9 }));
      var t = el('text', { 'class': 'lbl' + (last ? ' today' : ''), x: cx, y: H - padB + 24 });
      t.textContent = last ? '오늘' : d.d;
      svg.appendChild(t);
      // 월이 바뀌는 첫 날 표시
      if (i === 0 || data[i - 1].m !== d.m) {
        var mt = el('text', { 'class': 'lbl', x: cx, y: H - padB + 40 }); mt.textContent = d.m; svg.appendChild(mt);
      }
    }
  });
  // 오늘 값 툴팁
  var li = n - 1, tx = x(li), ty = y(data[li].v);
  var boxX = Math.min(tx - 40, W - padR - 92), boxY = Math.max(6, ty - 60);
  svg.appendChild(el('rect', { 'class': 'tip-box', x: boxX, y: boxY, width: 92, height: 42, rx: 3 }));
  var k = el('text', { 'class': 'tip-k', x: boxX + 8, y: boxY + 14 }); k.textContent = '일간 방문수'; svg.appendChild(k);
  var v = el('text', { 'class': 'tip-v', x: boxX + 8, y: boxY + 31 }); v.textContent = data[li].v; svg.appendChild(v);
  var diff = n > 1 ? data[li].v - data[li - 1].v : 0;
  var dt = el('text', { 'class': 'tip-d', x: boxX + 10 + String(data[li].v).length * 9 + 6, y: boxY + 31 });
  dt.textContent = (diff >= 0 ? '▲ ' : '▼ ') + Math.abs(diff); svg.appendChild(dt);
  svg.appendChild(el('line', { 'class': 'grid', x1: tx, x2: tx, y1: boxY + 42, y2: ty - 4, style: 'stroke:#ddd' }));
})();
